use std::fs
use std::json

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let r = json.parse_string::<Vec<Order>>(text)
    match r {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut sums: Vec<float> = []
            for o in orders {
                let mut add = 0.0
                for it in o.items {
                    add += (it.qty as float) * it.price
                }
                let mut idx: int = -1
                let mut i: int = 0
                while i < names.len() as int {
                    if names[i as usize] == o.customer {
                        idx = i
                    }
                    i += 1
                }
                if idx < 0 {
                    names.push(o.customer)
                    sums.push(add)
                } else {
                    sums[idx as usize] = sums[idx as usize] + add
                }
            }
            let mut order: Vec<string> = names.clone()
            order.sort()
            for n in order {
                let mut j: int = 0
                let mut k: int = 0
                while k < names.len() as int {
                    if names[k as usize] == n {
                        j = k
                    }
                    k += 1
                }
                let t: float = sums[j as usize]
                println("${n} ${t:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

